/** The page's own game script, run on HTML inside root; env gives it the page's helpers. */
export function run(root, env) {
  const document = { getElementById: (id) => root.querySelector('#' + id), createElement: (t) => globalThis.document.createElement(t) };
  const { APP_LANG, el, cssVar, safeGet, safeSet, SCX } = env;
  let holdLangHook = null;
  (function(){
  const levels = [
    { correct:20, en:'A block is pulled right with 20 N. Guess the force (to the left) that holds it at rest.', ta:'ஒரு பெட்டி வலப்புறம் 20 N விசையால் இழுக்கப்படுது. அதை ஓய்வுல பிடிக்க இடப்புறம் தேவையான விசையை யூகி.' },
    { correct:35, en:'A 35 N weight hangs on a cord. Guess the tension that holds it at rest.', ta:'ஒரு 35 N நிறை கயிறுல தொங்குது. அது ஓய்வுல இருக்க தேவையான இழுவையை யூகி.' },
    { correct:70, en:'A swing holds a child of weight 120 N. Rope 1 pulls up with 50 N. Guess the pull of rope 2.', ta:'ஒரு ஊஞ்சல்ல 120 N நிறையுள்ள பிள்ளை உக்காந்திருக்கு. கயிறு 1 மேல 50 N இழுக்குது. கயிறு 2 இழுவையை யூகி.' },
    { correct:40, en:'Two upward forces of 15 N and 25 N hold a hanging load. Guess the load\'s weight.', ta:'15 N, 25 N ஆகிய ரெண்டு மேல்நோக்கிய விசைகள் ஒரு தொங்கும் சுமையை பிடிச்சிருக்கு. சுமையின் நிறையை யூகி.' },
    { correct:54, en:'Boss level! A board weighs 84 N. Rope 1 pulls up 30 N. Guess the pull of rope 2.', ta:'பாஸ் லெவல்! ஒரு பலகையின் நிறை 84 N. கயிறு 1 மேல 30 N இழுக்குது. கயிறு 2 இழுவையை யூகி.' }
  ];
  const levelRow = document.getElementById('holdLevelRow');
  const levelDesc = document.getElementById('holdLevelDesc');
  const holdSvg = document.getElementById('holdSvg');
  const guessSlider = document.getElementById('holdGuessSlider');
  const guessVal = document.getElementById('holdGuessVal');
  const checkBtn = document.getElementById('holdCheckBtn');
  const resultEl = document.getElementById('holdResult');
  const starsEl = document.getElementById('holdStars');

  let curLevel = 0;
  let bestStars = JSON.parse(safeGet('scx_hold_stars') || '[0,0,0,0,0]');

  function drawScene(offset){
    holdSvg.innerHTML = '';
    const cx=280, cy=60+(offset||0);
    holdSvg.appendChild(el('line',{x1:cx-100,y1:14,x2:cx+100,y2:14,stroke:cssVar('--text-faint'),'stroke-width':3}));
    holdSvg.appendChild(el('circle',{cx:cx,cy:cy,r:18,fill:cssVar('--accent'),stroke:cssVar('--bg'),'stroke-width':3}));
    holdSvg.appendChild(el('line',{x1:cx,y1:14,x2:cx,y2:cy-18,stroke:cssVar('--text-faint'),'stroke-width':2,'stroke-dasharray':'3 3'}));
  }

  function renderLevelRow(){
    levelRow.innerHTML = '';
    levels.forEach((lv,i)=>{
      const b = document.createElement('div');
      b.className = 'level-btn' + (i===curLevel ? ' active' : '');
      const stars = bestStars[i] || 0;
      b.innerHTML = '<div class="lnum2">'+(i+1)+'</div><div class="lstars">'+('★'.repeat(stars)+'☆'.repeat(3-stars))+'</div>';
      b.addEventListener('click', ()=>{ curLevel = i; loadLevel(); });
      levelRow.appendChild(b);
    });
  }
  function loadLevel(){
    renderLevelRow();
    const lv = levels[curLevel];
    levelDesc.textContent = (APP_LANG==='ta') ? lv.ta : lv.en;
    resultEl.textContent = ''; resultEl.className = 'game-result';
    starsEl.textContent = '';
    drawScene(0);
  }
  guessSlider.addEventListener('input', ()=>{ guessVal.textContent = guessSlider.value; });

  checkBtn.addEventListener('click', ()=>{
    const lv = levels[curLevel];
    const guess = parseFloat(guessSlider.value);
    const err = Math.abs(guess - lv.correct);
    let stars;
    if(err <= 0.5) stars = 3;
    else if(err <= 2) stars = 2;
    else if(err <= 5) stars = 1;
    else stars = 0;
    drawScene(err <= 0.5 ? 0 : Math.max(-25, Math.min(25, (lv.correct - guess)*-1)));
    if(stars === 0){
      resultEl.textContent = (APP_LANG==='ta') ? '😅 நல்ல முயற்சி! சரியான பதில் '+lv.correct+' N.' : '😅 Nice try! The correct answer was '+lv.correct+' N.';
      resultEl.className = 'game-result lose';
      SCX.sndWrong();
    } else {
      resultEl.textContent = (APP_LANG==='ta') ? '🎉 சரியான விசை = '+lv.correct+' N — சமநிலை!' : '🎉 The correct force was '+lv.correct+' N — equilibrium!';
      resultEl.className = 'game-result win';
    }
    starsEl.textContent = stars>0 ? ('★'.repeat(stars) + '☆'.repeat(3-stars)) : '';

    const prevBest = bestStars[curLevel] || 0;
    if(stars > prevBest){
      bestStars[curLevel] = stars;
      safeSet('scx_hold_stars', JSON.stringify(bestStars));
      if(stars>0) SCX.pushItLevelResult(stars, bestStars.every(s=>s>0));
    } else if(stars>0){
      SCX.sndCorrect();
    }
    renderLevelRow();
  });

  loadLevel();
  holdLangHook = function(){ levelDesc.textContent = (APP_LANG==='ta') ? levels[curLevel].ta : levels[curLevel].en; renderLevelRow(); };
})();
  return { lang: () => holdLangHook && holdLangHook() };
}
